insert into public.recipes (id, name, description, meal_type, main, emoji, prep_time_min, difficulty, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, ingredients, seasonings, instructions, appliances, keywords, dietary_tags, sort) values
  ('b-banana-peanut-butter-oatmeal', 'Banana Peanut Butter Oatmeal', 'Creamy stovetop oats with sliced banana and a spoon of peanut butter', 'breakfast', 'oats', '🥣', 10, 'quick', 553, 21, 84, 17, 10, 30, 190, '[{"name":"oats","amount":60,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"peanut butter","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt","pinch of cinnamon"]'::jsonb, '["Put the oats, milk and a pinch of salt in a small pot over medium heat","Simmer for 4 to 5 minutes, stirring often, until thick and creamy","Slice the banana and stir half of it into the oats","Pour into a bowl and top with the rest of the banana, the peanut butter and a little cinnamon"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","milk","banana","peanut butter","stovetop","breakfast"]'::jsonb, '["vegetarian","halal","kosher"]'::jsonb, 0),
  ('b-apple-cinnamon-oatmeal', 'Apple Cinnamon Oatmeal', 'Warm oats cooked with diced apple, cinnamon and a drizzle of honey', 'breakfast', 'oats', '🍎', 12, 'quick', 480, 17, 86, 9, 10, 41, 127, '[{"name":"oats","amount":60,"unit":"g"},{"name":"milk","amount":250,"unit":"ml"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp cinnamon","pinch of salt"]'::jsonb, '["Core the apple and cut it into small cubes","Put the oats, milk, cinnamon, salt and two thirds of the apple in a small pot","Simmer over medium heat for 5 to 6 minutes, stirring often, until the oats are soft","Serve topped with the remaining apple and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","quick","oats","milk","apple","honey","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 1),
  ('b-coconut-berry-overnight-oats', 'Coconut Berry Overnight Oats', 'No-cook oats soaked overnight in coconut milk, topped with berries', 'breakfast', 'oats', '🫐', 5, 'quick', 456, 11, 61, 21, 10, 13, 16, '[{"name":"oats","amount":60,"unit":"g"},{"name":"coconut milk","amount":80,"unit":"g"},{"name":"blueberries","amount":80,"unit":"g"},{"name":"strawberries","amount":80,"unit":"g"}]'::jsonb, '["120 ml water","pinch of salt"]'::jsonb, '["Stir the oats, coconut milk, water and salt together in a jar or bowl","Cover and leave in the fridge overnight, or for at least 4 hours","In the morning stir well and loosen with a splash of water if it is too thick","Slice the strawberries and serve the oats topped with both berries"]'::jsonb, '[]'::jsonb, '["fresh","quick","oats","coconut milk","blueberries","strawberries","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 2),
  ('b-peanut-butter-banana-toast', 'Peanut Butter Banana Toast', 'Toasted wholemeal bread with peanut butter and banana slices', 'breakfast', 'bread', '🍌', 5, 'quick', 463, 17, 64, 18, 9, 21, 448, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"peanut butter","amount":30,"unit":"g"},{"name":"banana","amount":1,"unit":"","label":"1 banana"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Toast the bread until golden","Spread the peanut butter over both slices","Slice the banana, lay it on top and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["quick","bread","peanut butter","banana","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","halal","kosher"]'::jsonb, 3),
  ('b-avocado-tomato-toast', 'Avocado Tomato Toast', 'Smashed avocado on toast with fresh tomato, lemon and olive oil', 'breakfast', 'avocado', '🥑', 8, 'quick', 463, 12, 46, 28, 15, 7, 333, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"tomato","amount":100,"unit":"g"},{"name":"olive oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","squeeze of lemon juice","pinch of chili flakes"]'::jsonb, '["Toast the bread","Halve the avocado, scoop the flesh into a bowl and mash it with a fork, salt, pepper and a squeeze of lemon","Slice the tomato","Spread the avocado on the toast, top with tomato, drizzle with the olive oil and finish with chili flakes"]'::jsonb, '[]'::jsonb, '["fresh","light","quick","bread","avocado","tomato","olive oil","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 4),
  ('b-avocado-egg-toast', 'Avocado Toast with Fried Eggs', 'Wholemeal toast with smashed avocado and two fried eggs', 'breakfast', 'eggs', '🍳', 10, 'quick', 602, 25, 43, 38, 14, 4, 485, '[{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"avocado","amount":1,"unit":"","label":"1 avocado"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper","pinch of chili flakes"]'::jsonb, '["Toast the bread","Mash the avocado with salt and pepper and spread it over the toast","Heat the oil in a pan over medium heat and fry the eggs for 2 to 3 minutes until the whites are set","Slide an egg onto each slice and season with pepper and chili flakes"]'::jsonb, '["stovetop"]'::jsonb, '["hearty","quick","bread","avocado","eggs","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 5),
  ('b-greek-yogurt-berry-bowl', 'Greek Yogurt Berry Bowl', 'Thick Greek yogurt with blueberries, strawberries and honey', 'breakfast', 'greek yogurt', '🍓', 5, 'quick', 355, 24, 39, 13, 3, 33, 90, '[{"name":"greek yogurt","amount":250,"unit":"g"},{"name":"blueberries","amount":75,"unit":"g"},{"name":"strawberries","amount":75,"unit":"g"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '[]'::jsonb, '["Spoon the yogurt into a bowl","Halve or slice the strawberries","Top the yogurt with the berries and drizzle with the honey"]'::jsonb, '[]'::jsonb, '["fresh","light","quick","greek yogurt","blueberries","strawberries","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 6),
  ('b-apple-bircher-muesli', 'Apple Bircher Muesli', 'Oats soaked in yogurt with grated apple and honey', 'breakfast', 'yogurt', '🥣', 10, 'quick', 398, 13, 70, 9, 8, 37, 97, '[{"name":"yogurt","amount":200,"unit":"g"},{"name":"oats","amount":40,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Coarsely grate the apple, leaving the core behind","Stir the oats, yogurt, grated apple and cinnamon together in a bowl","Leave for at least 10 minutes, or overnight in the fridge, so the oats soften","Drizzle with the honey before serving"]'::jsonb, '[]'::jsonb, '["fresh","light","yogurt","oats","apple","honey","quick","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 7),
  ('b-spinach-feta-scrambled-eggs', 'Spinach and Feta Scrambled Eggs', 'Soft scrambled eggs with wilted spinach, feta and fresh tomato', 'breakfast', 'eggs', '🍳', 10, 'quick', 414, 30, 10, 29, 3, 4, 790, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"spinach","amount":80,"unit":"g"},{"name":"feta","amount":40,"unit":"g"},{"name":"tomato","amount":100,"unit":"g"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with a little pepper; the feta is salty, so add no salt","Melt the butter in a pan over medium heat and wilt the spinach for about 1 minute","Pour in the eggs and stir gently for 2 to 3 minutes until just set","Crumble in the feta, fold once and serve with the sliced tomato"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","quick","eggs","spinach","feta","tomato","butter","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 8),
  ('b-veggie-omelette', 'Pepper and Mushroom Omelette', 'A folded three-egg omelette filled with peppers, mushrooms and onion', 'breakfast', 'eggs', '🍳', 12, 'quick', 321, 24, 10, 21, 2, 6, 241, '[{"name":"eggs","amount":3,"unit":"","label":"3 eggs"},{"name":"peppers","amount":60,"unit":"g"},{"name":"mushrooms","amount":60,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["salt","black pepper"]'::jsonb, '["Dice the pepper and onion and slice the mushrooms","Heat the oil in a non-stick pan and cook the vegetables for 4 to 5 minutes until soft, then tip them onto a plate","Beat the eggs with salt and pepper, pour into the pan and cook over medium heat until almost set","Spoon the vegetables over one half, fold the omelette over and cook 1 more minute"]'::jsonb, '["stovetop"]'::jsonb, '["light","quick","eggs","peppers","mushrooms","onion","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 9),
  ('b-ham-cheese-omelette', 'Ham and Cheese Omelette with Toast', 'A quick omelette with ham and melted cheese, served with buttered toast', 'breakfast', 'eggs', '🧀', 10, 'quick', 454, 32, 18, 27, 3, 3, 919, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"ham","amount":40,"unit":"g"},{"name":"cheese","amount":30,"unit":"g"},{"name":"bread","amount":35,"unit":"g","label":"1 slice"},{"name":"butter","amount":5,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Beat the eggs with pepper, cut the ham into strips and grate the cheese","Melt half the butter in a non-stick pan over medium heat and pour in the eggs","When the eggs are almost set, scatter the ham and cheese over one half and fold the omelette over","Cook 1 more minute until the cheese melts and serve with the toasted, buttered bread"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","hearty","quick","eggs","ham","cheese","bread","butter","stovetop","breakfast"]'::jsonb, '["nut-allergy"]'::jsonb, 10),
  ('b-bacon-eggs-toast', 'Bacon and Eggs with Toast', 'Crispy bacon, fried eggs and pan-warmed tomato with toast', 'breakfast', 'eggs', '🥓', 15, 'quick', 548, 30, 35, 32, 5, 6, 855, '[{"name":"bacon","amount":50,"unit":"g"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"},{"name":"tomato","amount":100,"unit":"g"}]'::jsonb, '["black pepper"]'::jsonb, '["Lay the bacon in a cold pan and cook over medium heat for 5 to 6 minutes, turning once, until crisp, then move it to a plate","Halve the tomato and fry it cut side down in the bacon fat for 2 minutes","Fry the eggs in the same pan for 2 to 3 minutes until the whites are set","Toast the bread and serve everything together with a little pepper"]'::jsonb, '["stovetop"]'::jsonb, '["hearty","comfort","bacon","eggs","bread","tomato","stovetop","quick","breakfast"]'::jsonb, '["dairy-free","nut-allergy"]'::jsonb, 11),
  ('b-tofu-scramble-toast', 'Tofu Scramble on Toast', 'Golden scrambled tofu with spinach and peppers on wholemeal toast', 'breakfast', 'tofu', '🧈', 15, 'quick', 478, 37, 43, 21, 11, 7, 391, '[{"name":"tofu","amount":150,"unit":"g"},{"name":"spinach","amount":60,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":30,"unit":"g"},{"name":"oil","amount":5,"unit":"g"},{"name":"bread","amount":70,"unit":"g","label":"2 slices"}]'::jsonb, '["1/2 tsp turmeric","salt","black pepper"]'::jsonb, '["Finely dice the onion and pepper and cook them in the oil over medium heat for 3 minutes","Crumble the tofu into the pan with your hands and add the turmeric, salt and pepper","Cook for 4 to 5 minutes, stirring, until the tofu is hot and lightly golden","Stir in the spinach until it wilts and pile the scramble onto the toasted bread"]'::jsonb, '["stovetop"]'::jsonb, '["hearty","tofu","spinach","peppers","onion","oil","bread","stovetop","quick","breakfast"]'::jsonb, '["vegetarian","vegan","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 12),
  ('b-chickpea-potato-hash', 'Chickpea and Potato Breakfast Hash', 'Crispy pan-fried potatoes with chickpeas, onion and spinach', 'breakfast', 'chickpeas', '🥔', 25, 'balanced', 441, 14, 68, 14, 14, 9, 349, '[{"name":"potatoes","amount":200,"unit":"g"},{"name":"chickpeas","amount":120,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"spinach","amount":50,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp smoked paprika","salt","black pepper"]'::jsonb, '["Cut the potatoes into 1 cm cubes and dice the onion","Heat the oil in a wide pan and fry the potatoes over medium heat for 12 to 15 minutes, turning now and then, until golden and tender","Add the onion, drained chickpeas, paprika, salt and pepper and cook 4 more minutes","Stir in the spinach until it wilts and serve hot"]'::jsonb, '["stovetop"]'::jsonb, '["hearty","potatoes","chickpeas","onion","spinach","oil","stovetop","balanced","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 13),
  ('b-shakshuka', 'Shakshuka', 'Eggs poached in a spiced tomato and pepper sauce', 'breakfast', 'eggs', '🍅', 25, 'balanced', 342, 18, 23, 21, 8, 13, 451, '[{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"chopped tomatoes","amount":250,"unit":"g"},{"name":"peppers","amount":80,"unit":"g"},{"name":"onion","amount":60,"unit":"g"},{"name":"garlic","amount":8,"unit":"g","label":"2 cloves"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1 tsp ground cumin","1 tsp paprika","pinch of chili flakes","salt","black pepper"]'::jsonb, '["Slice the onion and pepper and finely chop the garlic","Heat the olive oil in a small pan and soften the onion and pepper for 5 minutes, then add the garlic and spices for 1 minute","Pour in the chopped tomatoes, season and simmer for 8 to 10 minutes until slightly thickened","Make two wells in the sauce, crack in the eggs, cover and cook 4 to 5 minutes until the whites are set"]'::jsonb, '["stovetop"]'::jsonb, '["mediterranean","spicy","comfort","eggs","chopped tomatoes","peppers","onion","garlic","olive oil","stovetop","balanced","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 14),
  ('b-cottage-cheese-apple-bowl', 'Cottage Cheese Bowl with Apple and Honey', 'High-protein cottage cheese with crisp apple, honey and cinnamon', 'breakfast', 'cottage cheese', '🍏', 5, 'quick', 320, 23, 40, 9, 4, 32, 632, '[{"name":"cottage cheese","amount":200,"unit":"g"},{"name":"apple","amount":1,"unit":"","label":"1 apple"},{"name":"honey","amount":10,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Spoon the cottage cheese into a bowl","Core the apple and cut it into thin slices or small cubes","Top the cottage cheese with the apple, drizzle with honey and dust with cinnamon"]'::jsonb, '[]'::jsonb, '["light","fresh","quick","cottage cheese","apple","honey","breakfast"]'::jsonb, '["vegetarian","gluten-free","nut-allergy","halal","kosher"]'::jsonb, 15),
  ('b-pancakes-strawberries', 'Pancakes with Strawberries', 'Thin homemade pancakes with fresh strawberries and honey', 'breakfast', 'flour', '🥞', 25, 'balanced', 508, 18, 72, 17, 4, 24, 203, '[{"name":"flour","amount":60,"unit":"g"},{"name":"eggs","amount":1,"unit":"","label":"1 egg"},{"name":"milk","amount":120,"unit":"ml"},{"name":"butter","amount":10,"unit":"g"},{"name":"strawberries","amount":100,"unit":"g"},{"name":"honey","amount":15,"unit":"g"}]'::jsonb, '["pinch of salt"]'::jsonb, '["Whisk the flour, egg, milk and salt into a smooth batter and let it rest for 5 minutes","Melt a little of the butter in a non-stick pan over medium heat","Pour in a thin layer of batter, cook about 1 minute per side until golden, and repeat with the rest of the batter","Slice the strawberries and serve the pancakes topped with them and the honey"]'::jsonb, '["stovetop"]'::jsonb, '["comfort","flour","eggs","milk","butter","strawberries","honey","stovetop","balanced","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 16),
  ('b-banana-egg-pancakes', 'Banana Egg Pancakes', 'Flourless two-ingredient pancakes with blueberries', 'breakfast', 'eggs', '🥞', 12, 'quick', 343, 16, 37, 16, 5, 21, 158, '[{"name":"banana","amount":1,"unit":"","label":"1 banana"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"blueberries","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of cinnamon"]'::jsonb, '["Mash the banana very smooth in a bowl, then whisk in the eggs and cinnamon","Heat the oil in a non-stick pan over medium-low heat","Drop in small spoonfuls of batter and cook about 2 minutes per side, turning carefully","Serve topped with the blueberries"]'::jsonb, '["stovetop"]'::jsonb, '["light","quick","banana","eggs","blueberries","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 17),
  ('b-breakfast-burrito', 'Breakfast Burrito', 'A warm tortilla filled with scrambled eggs, beans, cheese and tomato', 'breakfast', 'eggs', '🌯', 12, 'quick', 559, 30, 46, 28, 6, 7, 944, '[{"name":"tortilla","amount":1,"unit":"","label":"1 tortilla"},{"name":"eggs","amount":2,"unit":"","label":"2 eggs"},{"name":"kidney beans","amount":60,"unit":"g"},{"name":"cheese","amount":25,"unit":"g"},{"name":"tomato","amount":60,"unit":"g"},{"name":"oil","amount":5,"unit":"g"}]'::jsonb, '["pinch of ground cumin","salt","black pepper"]'::jsonb, '["Dice the tomato, grate the cheese and drain the beans","Heat the oil in a pan, warm the beans with the cumin for 1 minute, then pour in the beaten eggs and scramble until just set","Warm the tortilla in a dry pan for 20 seconds per side","Fill it with the eggs and beans, cheese and tomato, fold in the sides and roll up"]'::jsonb, '["stovetop"]'::jsonb, '["mexican","hearty","quick","tortilla","eggs","kidney beans","cheese","tomato","oil","stovetop","breakfast"]'::jsonb, '["vegetarian","nut-allergy","halal","kosher"]'::jsonb, 18),
  ('b-sweet-potato-bean-hash', 'Sweet Potato and Bean Hash', 'Pan-fried sweet potato with kidney beans, peppers and onion', 'breakfast', 'sweet potato', '🍠', 25, 'balanced', 420, 12, 70, 12, 14, 17, 346, '[{"name":"sweet potato","amount":200,"unit":"g"},{"name":"kidney beans","amount":100,"unit":"g"},{"name":"peppers","amount":60,"unit":"g"},{"name":"onion","amount":50,"unit":"g"},{"name":"olive oil","amount":10,"unit":"g"}]'::jsonb, '["1/2 tsp ground cumin","1/2 tsp smoked paprika","salt","black pepper"]'::jsonb, '["Peel the sweet potato and cut it into 1 cm cubes; dice the onion and pepper","Heat the olive oil in a wide pan and fry the sweet potato over medium heat for 10 to 12 minutes until tender and browned","Add the onion, pepper and spices and cook 4 more minutes","Stir in the drained beans, heat through for 2 minutes and season to taste"]'::jsonb, '["stovetop"]'::jsonb, '["hearty","mexican","sweet potato","kidney beans","peppers","onion","olive oil","stovetop","balanced","breakfast"]'::jsonb, '["vegetarian","vegan","gluten-free","dairy-free","nut-allergy","halal","kosher"]'::jsonb, 19),
  ('1', 'Chicken Rice 1', 'Chicken with rice, onion and pesto', 'dinner', 'chicken', '🍗', 41, 'balanced', 770, 53, 71, 29, 3, 5, 397, '[{"name":"chicken","amount":200,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"onion","amount":100,"unit":"g"},{"name":"pesto","amount":30,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["salt","pepper"]'::jsonb, '["Batch cook chicken (store for 2–3 meals)","Prepare rice in bulk","Cook onion","Combine chicken with pesto","Serve with rice"]'::jsonb, '["stovetop","oven"]'::jsonb, '["italian","hearty","chicken","rice","onion","pesto","oil","stovetop","oven","balanced","dinner"]'::jsonb, '["gluten-free","halal"]'::jsonb, 20),
  ('2', 'Chicken Rice 2', 'Chicken with rice, carrots and soy sauce', 'lunch', 'chicken', '🍗', 51, 'weekend', 654, 53, 71, 16, 4, 5, 1261, '[{"name":"chicken","amount":200,"unit":"g"},{"name":"rice","amount":75,"unit":"g"},{"name":"carrots","amount":100,"unit":"g"},{"name":"soy sauce","amount":20,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["salt","pepper"]'::jsonb, '["Batch cook chicken (store for 2–3 meals)","Marinate the chicken for better flavor","Prepare rice in bulk","Cook carrots","Combine chicken with soy sauce","Serve with rice","Plate carefully and add garnish"]'::jsonb, '["air fryer","oven"]'::jsonb, '["asian","hearty","chicken","rice","carrots","soy sauce","oil","air fryer","oven","weekend","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 21),
  ('3', 'Chicken Pasta 3', 'Chicken with pasta, onion and teriyaki', 'lunch', 'chicken', '🍗', 10, 'quick', 682, 58, 72, 16, 4, 12, 1632, '[{"name":"chicken","amount":200,"unit":"g"},{"name":"pasta","amount":75,"unit":"g"},{"name":"onion","amount":100,"unit":"g"},{"name":"teriyaki","amount":40,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["salt","pepper"]'::jsonb, '["Batch cook chicken (store for 2–3 meals)","Prepare pasta in bulk","Cook onion","Combine chicken with teriyaki","Serve with pasta"]'::jsonb, '["oven"]'::jsonb, '["asian","italian","hearty","quick","chicken","pasta","onion","teriyaki","oil","oven","lunch"]'::jsonb, '["dairy-free","nut-allergy","halal","kosher"]'::jsonb, 22),
  ('4', 'Chicken Pasta 4', 'Chicken with pasta, peppers and pesto', 'dinner', 'chicken', '🍗', 22, 'quick', 760, 57, 64, 29, 5, 7, 398, '[{"name":"chicken","amount":200,"unit":"g"},{"name":"pasta","amount":75,"unit":"g"},{"name":"peppers","amount":100,"unit":"g"},{"name":"pesto","amount":30,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["salt","pepper"]'::jsonb, '["Batch cook chicken (store for 2–3 meals)","Prepare pasta in bulk","Cook peppers","Combine chicken with pesto","Serve with pasta"]'::jsonb, '["stovetop"]'::jsonb, '["italian","hearty","quick","chicken","pasta","peppers","pesto","oil","stovetop","dinner"]'::jsonb, '["halal"]'::jsonb, 23),
  ('5', 'Chicken Potatoes 5', 'Chicken with potatoes, carrots and pesto', 'lunch', 'chicken', '🍗', 41, 'balanced', 690, 52, 55, 28, 9, 7, 473, '[{"name":"chicken","amount":200,"unit":"g"},{"name":"potatoes","amount":250,"unit":"g"},{"name":"carrots","amount":100,"unit":"g"},{"name":"pesto","amount":30,"unit":"g"},{"name":"oil","amount":10,"unit":"g"}]'::jsonb, '["salt","pepper"]'::jsonb, '["Batch cook chicken (store for 2–3 meals)","Prepare potatoes in bulk","Cook carrots","Combine chicken with pesto","Serve with potatoes"]'::jsonb, '["microwave","oven","slow cooker"]'::jsonb, '["italian","hearty","chicken","potatoes","carrots","pesto","oil","microwave","oven","slow cooker","balanced","lunch"]'::jsonb, '["gluten-free","halal"]'::jsonb, 24),
